"use client";

import { useEffect, useState } from "react";
import { supabase } from "@/lib/supabase";
import { Loader2 } from "lucide-react";
import StoreSettings from "@/components/dashboard/StoreSettings";
import {
  PROFILE_STOREFRONT_SELECT,
  profileRowToLegacyStoreShape,
  type ProfileStorefrontRow,
} from "@/lib/profileAsStorefront";

export default function SettingsPage() {
  const [store, setStore] = useState<any>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function fetchStore() {
      const {
        data: { user },
      } = await supabase.auth.getUser();
      if (!user) {
        setLoading(false);
        return;
      }

      const [{ data: storeData }, { data: prof, error: profErr }] = await Promise.all([
        supabase.from("stores").select("*").eq("owner_id", user.id).maybeSingle(),
        supabase.from("profiles").select(PROFILE_STOREFRONT_SELECT).eq("id", user.id).maybeSingle(),
      ]);

      if (profErr || !prof) {
        setStore(null);
        setLoading(false);
        return;
      }

      const profRow = prof as unknown as ProfileStorefrontRow;
      const synthetic = profileRowToLegacyStoreShape(profRow, {
        legacyStoreId: storeData?.id ?? null,
        ownerEmail: user.email ?? undefined,
      });

      const ig = profRow.instagram_handle?.trim() || "";
      const tt = profRow.tiktok_url?.trim() || "";

      const storeForUi = storeData
        ? {
            ...synthetic,
            id: storeData.id,
            owner_id: user.id,
            __surface: "merged" as const,
            __legacy_store_id: storeData.id,
            instagram_handle: ig || storeData.instagram_handle || "",
            tiktok_url: tt || storeData.tiktok_url || "",
            cover_image_url: storeData.cover_image_url ?? synthetic.cover_image_url,
          }
        : {
            ...synthetic,
            owner_id: user.id,
            instagram_handle: ig,
            tiktok_url: tt,
          };

      setStore(storeForUi);
      setLoading(false);
    }
    fetchStore();
  }, []);

  if (loading) {
    return (
      <div className="flex h-[50vh] items-center justify-center">
        <Loader2 className="animate-spin text-gray-300" size={32} />
      </div>
    );
  }

  if (!store) {
    return (
      <div className="p-8 text-center text-gray-500">
        Could not load your seller profile. Try signing in again or contact support.
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto pb-12">
      <div className="mb-8">
        <h1 className="text-3xl font-black text-gray-900">Settings</h1>
        <p className="text-gray-500">Manage your storefront details — synced with your StoreLink profile.</p>
      </div>

      <StoreSettings store={store} />
    </div>
  );
}
